// 1. You write this simple C# class (The Blueprint)
public class User {
    public int Id { get; set; }
    public string Name { get; set; }
}

// 2. You tell EF Core to build it using "Migrations"
// Terminal Command: dotnet ef database update

// 3. EF Core secretly writes and runs this SQL for you:
/*
CREATE TABLE Users (
    Id INT PRIMARY KEY IDENTITY,
    Name NVARCHAR(MAX)
);
*/

// ✅ EAGER LOADING (The Safe Way)
var user = await db.Users
    .Include(u => u.Orders)     // Grab orders right now!
    .FirstAsync();              // Hits the database ONCE.

// We already have the orders, no extra database trips needed.
Console.WriteLine(user.Orders.Count);


// ⚠️ LAZY LOADING (The Dangerous Way)
var user = await db.Users.FirstAsync(); // Hits the database ONCE.

// Oh wait! We are asking for the Orders now.
// EF Core silently pauses the program and hits the database AGAIN!
Console.WriteLine(user.Orders.Count);

// ❌ THE BAD WAY (Makes 101 trips to the database!)
var users = await db.Users.ToListAsync(); // Trip 1

foreach (var user in users) {
    // DANGER: We are inside a loop!
    // Just typing 'user.Orders' makes EF Core secretly talk to the database.
    var orderCount = user.Orders.Count;   // Trips 2 through 101 happen here!
    Console.WriteLine($"{user.Name} has {orderCount} orders");
}


// ✅ THE GOOD WAY (Makes exactly 1 trip to the database!)
var users = await db.Users
    .Include(u => u.Orders)               // <-- THE MAGIC FIX!
    .ToListAsync();                       // Trip 1 (and only trip)

foreach (var user in users) {
    // EF Core already got the orders, so it doesn't need to talk to the database again.
    Console.WriteLine($"{user.Name} has {user.Orders.Count} orders");
}

// ❌ THE SLOW WAY (Wastes memory tracking changes we never make)
var users = await db.Users.ToListAsync();
return Ok(users); // We are just returning them to a webpage!


// ✅ THE FAST WAY (Tells EF Core not to track them)
var users = await db.Users
    .AsNoTracking()         // <-- The magic speed boost!
    .ToListAsync();
return Ok(users);


// ⚠️ THE MISTAKE (Updating untracked data)
var user = await db.Users.AsNoTracking().FirstAsync();
user.Name = "Bob";

// Nothing happens! EF Core wasn't tracking the user, 
// so it doesn't know the name changed.
await db.SaveChangesAsync();

// ❌ THE OLD WAY (Creating a wrapper that does nothing useful)
public class UserRepository {
    private readonly DbContext _db;
    public void Add(User user) {
        _db.Users.Add(user); // Why not just call this directly?
    }
}

// ✅ THE MODERN WAY (Just use DbContext directly for simple stuff!)
public class UserController {
    private readonly AppDbContext _db;

    public async Task CreateUser(User user) {
        _db.Users.Add(user);
        await _db.SaveChangesAsync();
    }
}

// 🚀 WHEN TO ACTUALLY USE A REPOSITORY (Hiding complex queries)
public class ReportRepository {
    public async Task<List<User>> GetUsersWhoPurchasedInLast30Days() {
        // Hide this massive, ugly LINQ query inside the repository!
        return await _db.Users
            .Include(u => u.Orders)
            .Where(u => u.Orders.Any(o => o.Date >= DateTime.Now.AddDays(-30)))
            .OrderBy(u => u.Name)
            .ToListAsync();
    }
}
